  const archiveLocked=()=>{if(!authenticated){login();return}setOpenArchive(null);setTab("subscribe")};
  useEffect(()=>{if(!canOpenArchives&&openArchive)setOpenArchive(null)},[canOpenArchives,openArchive]);
  const submitSearch=value=>{setSearchQuery(value);setOpen(null);setOpenArchive(null);setTab("discover");setMenuOpen(false)};
